"""One input, many outputs: send the value to exactly one chosen output port.

The combo box lists output port names (not 1/2/3), so it reads like
「这次走 优化器A / 优化器B / 优化器C」. Ports that were not chosen return an
``ExecutionBlocker`` so their branches are skipped instead of running with a
wrong value.
"""

from __future__ import annotations

import copy
import logging
from typing import Any

try:  # ExecutionBlocker 只在较新的 ComfyUI 提供，缺失时降级为「不阻塞」
    from comfy_execution.graph import ExecutionBlocker
except Exception:  # pragma: no cover - 只在没有 ComfyUI 运行时的测试里发生
    ExecutionBlocker = None


MAX_OUTPUTS = 8
FIRST_OUTPUT_NAME = "输出1"

# 输入没接时 ComfyUI 不会传 value，用哨兵区分「没接」和「接了个 None」
_UNSET = object()


def _output_names() -> tuple[str, ...]:
    return tuple(f"输出{index + 1}" for index in range(MAX_OUTPUTS))


def _blocker(message: str | None = None) -> Any:
    """Blocked value for an unselected port; None when the runtime lacks it."""
    if ExecutionBlocker is None:
        return None
    return ExecutionBlocker(message)


def _attempted_names(choice: str) -> list[str]:
    """Names a single choice may refer to, most specific first."""
    names = [choice]
    for prefix in ("输出", "output", "Output", "OUTPUT"):
        if choice.startswith(prefix) and choice[len(prefix) :].strip().isdigit():
            names.append(choice[len(prefix) :].strip())
            break
    if choice.isdigit():
        names.append(f"输出{choice}")
    return names


def _numeric_index(choice: str) -> int | None:
    """``3`` / ``输出3`` / ``output3`` 都按 1 起算的口序解析, 越界返回 None."""
    digits = choice
    for prefix in ("输出", "output", "Output", "OUTPUT"):
        if digits.startswith(prefix):
            digits = digits[len(prefix) :].strip()
            break
    if not digits.isdigit():
        return None
    index = int(digits) - 1
    return index if 0 <= index < MAX_OUTPUTS else None


def _workflow_output_entries(unique_id: Any, extra_pnginfo: Any) -> list[dict[str, Any]]:
    """Output slot dicts of this node as stored in the workflow, in slot order."""
    if extra_pnginfo is None or unique_id is None:
        return []
    try:
        nodes = extra_pnginfo.get("workflow", {}).get("nodes", []) or []
    except AttributeError:  # 结构不符合预期，按「没有信息」处理
        return []
    for node in nodes:
        if not isinstance(node, dict) or str(node.get("id")) != str(unique_id):
            continue
        outputs = node.get("outputs") or []
        # 数组顺序就是端口顺序：序列化时 outputs 是逐个 asSerialisable 出来的
        return [entry for entry in outputs if isinstance(entry, dict)]
    return []


def resolve_output_index(select: Any, unique_id: Any = None, extra_pnginfo: Any = None) -> int:
    """把选择框的值解析成 0 起的输出口序号。

    认三种写法：用户改过的输出口名称（label）、默认口名 ``输出N``、纯数字 ``N``。
    都对不上时退回第一个口，保证旧工作流不会因为改名而整条跑失败。
    """
    choice = str(select if select is not None else "").strip()
    entries = _workflow_output_entries(unique_id, extra_pnginfo)
    candidates = _attempted_names(choice)

    for index, entry in enumerate(entries):
        for key in ("label", "localized_name", "name"):
            value = entry.get(key)
            if isinstance(value, str) and value.strip() in candidates:
                return index

    numeric = _numeric_index(choice)
    if numeric is not None:
        return numeric

    logging.warning("QQRouteDispatch: 选择框的值 %r 对不上任何输出口，改走第一个输出", select)
    return 0


class QQRouteDispatch:
    CATEGORY = "QQ/工具"
    FUNCTION = "dispatch"
    RETURN_TYPES = ("*",) * MAX_OUTPUTS
    RETURN_NAMES = _output_names()
    OUTPUT_IS_LIST = (False,) * MAX_OUTPUTS
    DESCRIPTION = (
        "一个输入按条件只送一个输出口。下拉框列的是输出口名称（不是 1、2、3），"
        "重命名输出口后自动跟着变；没被选中的输出口静默阻塞，下游分支不会执行。"
        "输入是通配口，文本、图像、任何类型都能接。"
        "打开「轮询输出」后改为按次序轮换：每次运行只走下一个已连接的口，"
        "前端会自动连续排队，直到所有已连接的口各跑过一次，选择框置灰不可改。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "轮询输出": ("BOOLEAN", {"default": False, "label_on": "轮询", "label_off": "关闭"}),
                "select": ([FIRST_OUTPUT_NAME], {"default": FIRST_OUTPUT_NAME}),
            },
            "optional": {
                "value": ("*", {"forceInput": True}),
            },
            "hidden": {"unique_id": "UNIQUE_ID", "extra_pnginfo": "EXTRA_PNGINFO"},
        }

    @classmethod
    def VALIDATE_INPUTS(cls, select, **kwargs):
        # 输出口由前端动态增减并改名，静态 INPUT_TYPES 里的可选列表只是占位，
        # 不能拿它来校验 select。
        return True

    @staticmethod
    def dispatch(
        select: Any = FIRST_OUTPUT_NAME,
        value: Any = _UNSET,
        unique_id: Any = None,
        extra_pnginfo: Any = None,
        轮询输出: Any = False,
        **_kwargs: Any,
    ):
        blocked = _blocker()
        # 输入没接：所有口都堵上，避免下游拿到 None 白跑一趟
        if value is _UNSET:
            return tuple(blocked for _ in range(MAX_OUTPUTS))

        # 轮询模式也复用 select：前端每次排队前会把 select 改成下一个口，
        # 所以后端不需要额外状态，也不受 IS_CHANGED 缓存影响。
        chosen = resolve_output_index(select, unique_id, extra_pnginfo)
        outputs = [blocked] * MAX_OUTPUTS
        outputs[chosen] = value
        return tuple(outputs)


def _select_widget_position() -> int:
    """select 在 widgets_values 里的下标（控件顺序固定 [轮询输出, select]）。"""
    required = QQRouteDispatch.INPUT_TYPES().get("required", {})
    names = [
        name
        for name, spec in required.items()
        if not (
            isinstance(spec, (list, tuple))
            and len(spec) > 1
            and isinstance(spec[1], dict)
            and spec[1].get("forceInput")
        )
    ]
    return names.index("select") if "select" in names else 1


def polling_plan(prompt: Any, graph: Any) -> list[tuple[str, list[int]]]:
    """开轮询的顶层分发节点 → (prompt 里的执行 id, 已连接口序号)。

    连线信息只在 workflow 存档里（prompt 没有 links），与前端
    connectedIndexes 同一口径：outputs[i].links 非空即已连接。
    """
    top: dict[str, Any] = {}
    if isinstance(graph, dict):
        top = {
            str(node.get("id")): node
            for node in graph.get("nodes") or []
            if isinstance(node, dict)
        }
    plan: list[tuple[str, list[int]]] = []
    for exec_id, node in (prompt or {}).items():
        if not isinstance(node, dict) or node.get("class_type") != "QQRouteDispatch":
            continue
        if not (node.get("inputs") or {}).get("轮询输出"):
            continue
        outputs = (top.get(str(exec_id)) or {}).get("outputs") or []
        linked = [
            index
            for index, entry in enumerate(outputs)
            if isinstance(entry, dict) and entry.get("links")
        ]
        if linked:
            plan.append((str(exec_id), linked))
    return plan


def expand_polling(prompt: dict[str, Any], graph: Any) -> list[tuple[dict[str, Any], Any]]:
    """手机端轮询展开：每个已连接的口克隆一份 prompt+存档并改写 select。

    与前端 patchPollingRound 同语义：inputs.select 与存档 widgets_values 里的
    select 一起改写（条件收集的自动跟随读存档）；口数不齐的节点夹到最后一个口。
    没开轮询时原样返回单份，调用方无需分支。
    """
    plan = polling_plan(prompt, graph)
    if not plan:
        return [(prompt, graph)]
    position = _select_widget_position()
    rounds = max(len(linked) for _, linked in plan)
    pairs: list[tuple[dict[str, Any], Any]] = []
    for round_index in range(rounds):
        run_prompt = copy.deepcopy(prompt)
        run_graph = copy.deepcopy(graph) if isinstance(graph, dict) else graph
        top = (
            {str(node.get("id")): node for node in run_graph.get("nodes") or []}
            if isinstance(run_graph, dict)
            else {}
        )
        for exec_id, linked in plan:
            index = linked[min(round_index, len(linked) - 1)]
            entry = (top.get(exec_id) or {}).get("outputs") or []
            name = f"输出{index + 1}"
            if index < len(entry) and isinstance(entry[index], dict):
                label = entry[index].get("label") or entry[index].get("name")
                if isinstance(label, str) and label.strip():
                    name = label.strip()
            run_prompt[exec_id].setdefault("inputs", {})["select"] = name
            values = (top.get(exec_id) or {}).get("widgets_values")
            if isinstance(values, list) and position < len(values):
                values[position] = name
        pairs.append((run_prompt, run_graph))
    return pairs


NODE_CLASS_MAPPINGS = {"QQRouteDispatch": QQRouteDispatch}
NODE_DISPLAY_NAME_MAPPINGS = {"QQRouteDispatch": "QQ-条件分发"}
